def nucleus(probs,p):
    if not 0<p<=1: raise ValueError('p')
    out=[];mass=0
    for i,v in sorted(enumerate(probs),key=lambda x:-x[1]):
        out.append(i);mass+=v
        if mass>=p: break
    return out

